                     nL = 1;
                     WHILE( nL <= nD );
                        vM = DIMNM( 'WFP FX Rates Measure', nL );
                        IF( DTYPE( 'WFP FX Rates Measure', vM ) @= 'N' );
                           nVal = CellGetN( cFX, vP, pSource, vCur, vRt, vM );
                           IF( nVal <> 0 ); CellPutN( nVal, cFX, vP, pTarget, vCur, vRt, vM ); nCopied = nCopied + 1; ENDIF;
